text:
.subviewbutton.panel-subview-footer {
  box-sizing: border-box;
  min-block-size: 41px;
  margin: 0;
  background-color: var(--panel-background-color-dimmed);
  border-block-start: 1px solid var(--panel-separator-color);
  border-radius: 0;

  .cui-widget-panelview menuitem& {
    margin: 4px 0 0;
  }
